import { test, expect } from '@playwright/test';

test.describe('Accessibility - Login Fields and Product Images', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should have non-empty placeholder attributes on login fields', async ({ page }) => {
    const usernameField = page.getByTestId('username');
    const passwordField = page.getByTestId('password');

    const usernamePlaceholder = await usernameField.getAttribute('placeholder');
    const passwordPlaceholder = await passwordField.getAttribute('placeholder');

    expect(usernamePlaceholder).toBeTruthy();
    expect(usernamePlaceholder).not.toBe('');
    expect(passwordPlaceholder).toBeTruthy();
    expect(passwordPlaceholder).not.toBe('');
  });

  test('should have non-empty alt attributes on all product images after login', async ({ page }) => {
    const usernameField = page.getByTestId('username');
    const passwordField = page.getByTestId('password');
    const loginButton = page.getByRole('button', { name: /login/i });

    await usernameField.fill('standard_user');
    await passwordField.fill('secret_sauce');
    await loginButton.click();

    await page.waitForURL('**/inventory.html');

    const productImages = page.locator('img.inventory_item_img');
    const imageCount = await productImages.count();

    expect(imageCount).toBeGreaterThan(0);

    for (let i = 0; i < imageCount; i++) {
      const image = productImages.nth(i);
      const altText = await image.getAttribute('alt');

      expect(altText).toBeTruthy();
      expect(altText).not.toBe('');
    }
  });

  test('should verify login fields are accessible with proper labels', async ({ page }) => {
    const usernameField = page.getByTestId('username');
    const passwordField = page.getByTestId('password');

    await expect(usernameField).toBeVisible();
    await expect(passwordField).toBeVisible();

    const usernameRole = await usernameField.getAttribute('type');
    const passwordRole = await passwordField.getAttribute('type');

    expect(usernameRole).toBe('text');
    expect(passwordRole).toBe('password');
  });

  test('should verify product images are properly nested within inventory items', async ({ page }) => {
    const usernameField = page.getByTestId('username');
    const passwordField = page.getByTestId('password');
    const loginButton = page.getByRole('button', { name: /login/i });

    await usernameField.fill('standard_user');
    await passwordField.fill('secret_sauce');
    await loginButton.click();

    await page.waitForURL('**/inventory.html');

    const inventoryItems = page.locator('.inventory_item');
    const itemCount = await inventoryItems.count();

    expect(itemCount).toBeGreaterThan(0);

    for (let i = 0; i < itemCount; i++) {
      const item = inventoryItems.nth(i);
      const image = item.locator('img.inventory_item_img');

      await expect(image).toBeVisible();

      const altText = await image.getAttribute('alt');
      expect(altText).toBeTruthy();
      expect(altText?.length).toBeGreaterThan(0);
    }
  });
});
